const DEFAULTS = {
  stepPercent: 1,
  shiftWheelStepPercent: 5,
  shiftWheelMode: "zoom", // off | zoom
  minZoom: 0.25,
  maxZoom: 5,
  ctrlWheelMode: "zoom", // off | zoom | block
  scrollThreshold: 40,
  minDelayMs: 80,
  directionReversed: false,
  smoothScroll: true,
  shortcuts: {
    zoomIn: "Ctrl+Shift+ArrowUp",
    zoomOut: "Ctrl+Shift+ArrowDown",
    zoomReset: "Ctrl+Shift+0"
  },
  shortcutDisabledHosts: []
};

let settings = { ...DEFAULTS };
let lastWheelTime = 0;

function loadSettings() {
  chrome.storage.sync.get(DEFAULTS, (items) => {
    settings = {
      ...DEFAULTS,
      ...items,
      shortcuts: {
        ...DEFAULTS.shortcuts,
        ...(items.shortcuts || {})
      }
    };
  });
}

chrome.storage.onChanged.addListener((changes, area) => {
  if (area !== "sync") return;
  for (const [key, change] of Object.entries(changes)) {
    if (key === "shortcuts") {
      settings.shortcuts = {
        ...DEFAULTS.shortcuts,
        ...(change.newValue || {})
      };
      continue;
    }
    if (key === "shortcutDisabledHosts") {
      settings.shortcutDisabledHosts = Array.isArray(change.newValue)
        ? change.newValue
        : [];
      continue;
    }
    settings[key] = change.newValue;
  }
});

loadSettings();

function shouldHandleWheel(event) {
  if (!event.cancelable) return false;
  const ctrlOrCmd = event.ctrlKey || event.metaKey;
  if (!ctrlOrCmd) return false;
  if (settings.ctrlWheelMode === "off") return false;
  return true;
}

function shouldHandleShiftWheel(event) {
  if (!event.cancelable) return false;
  if (settings.shiftWheelMode === "off") return false;
  if (!event.shiftKey) return false;
  if (event.ctrlKey || event.metaKey || event.altKey) return false;
  return true;
}

function canTrigger(deltaY) {
  const now = Date.now();
  if (Math.abs(deltaY) < settings.scrollThreshold) return false;
  if (now - lastWheelTime < settings.minDelayMs) return false;
  lastWheelTime = now;
  return true;
}

function handleWheel(event) {
  if (shouldHandleShiftWheel(event)) {
    const deltaY = event.deltaY || 0;
    if (!canTrigger(deltaY)) return;
    event.preventDefault();

    const direction = deltaY < 0 ? 1 : -1;
    const adjusted = settings.directionReversed ? -direction : direction;

    chrome.runtime.sendMessage({
      type: "wheelZoom",
      direction: adjusted,
      stepPercent: settings.shiftWheelStepPercent
    });
    return;
  }

  if (!shouldHandleWheel(event)) return;

  const deltaY = event.deltaY || 0;
  if (!canTrigger(deltaY)) return;

  event.preventDefault();

  if (settings.ctrlWheelMode === "block") {
    if (settings.smoothScroll) {
      window.scrollBy({ left: event.deltaX, top: deltaY, behavior: "smooth" });
    } else {
      window.scrollBy(event.deltaX, deltaY);
    }
    return;
  }

  const direction = deltaY < 0 ? 1 : -1;
  const adjusted = settings.directionReversed ? -direction : direction;

  chrome.runtime.sendMessage({
    type: "wheelZoom",
    direction: adjusted
  });
}

function keyFromCode(code) {
  if (!code) return "";
  if (/^Key[A-Z]$/.test(code)) return code.slice(3);
  if (/^Digit[0-9]$/.test(code)) return code.slice(5);
  if (/^Numpad[0-9]$/.test(code)) return code;

  const direct = new Set([
    "ArrowUp",
    "ArrowDown",
    "ArrowLeft",
    "ArrowRight",
    "Escape",
    "Tab",
    "Enter",
    "Backspace",
    "Delete",
    "Home",
    "End",
    "PageUp",
    "PageDown",
    "Insert",
    "Space",
    "NumpadAdd",
    "NumpadSubtract",
    "NumpadMultiply",
    "NumpadDivide",
    "NumpadDecimal"
  ]);
  if (direct.has(code)) return code;

  return "";
}

function normalizeShortcutKey(event) {
  const codeKey = keyFromCode(event.code);
  if (codeKey) return codeKey;

  const key = event.key;
  if (!key) return "";
  if (key === " ") return "Space";
  if (key === "Esc") return "Escape";
  if (key === "Spacebar") return "Space";

  const modifiers = new Set(["Shift", "Control", "Alt", "Meta"]);
  if (modifiers.has(key)) return "";

  return key.length === 1 ? key.toUpperCase() : key;
}

function buildShortcut(event) {
  const key = normalizeShortcutKey(event);
  if (!key) return "";

  const parts = [];
  if (event.ctrlKey) parts.push("Ctrl");
  if (event.altKey) parts.push("Alt");
  if (event.shiftKey) parts.push("Shift");
  if (event.metaKey) parts.push("Meta");
  parts.push(key);
  return parts.join("+");
}

function shortcutEquals(a, b) {
  return String(a || "").toLowerCase() === String(b || "").toLowerCase();
}

function isEditableTarget(target) {
  if (!(target instanceof Element)) return false;
  if (target.isContentEditable) return true;
  if (target.closest("[contenteditable='true']")) return true;

  const tagName = target.tagName;
  return tagName === "INPUT" || tagName === "TEXTAREA" || tagName === "SELECT";
}

function isShortcutHostDisabled(hostname) {
  const host = String(hostname || "").toLowerCase();
  if (!host) return false;

  const disabledHosts = Array.isArray(settings.shortcutDisabledHosts)
    ? settings.shortcutDisabledHosts
    : [];

  return disabledHosts.some((entry) => {
    const normalized = String(entry || "").toLowerCase().replace(/^\./, "");
    if (!normalized) return false;
    return host === normalized || host.endsWith(`.${normalized}`);
  });
}

function handleKeydown(event) {
  if (event.defaultPrevented || event.repeat) return;
  if (isEditableTarget(event.target)) return;
  if (isShortcutHostDisabled(window.location.hostname)) return;

  const shortcut = buildShortcut(event);
  if (!shortcut) return;

  const shortcuts = settings.shortcuts || DEFAULTS.shortcuts;
  let command = "";
  if (shortcutEquals(shortcut, shortcuts.zoomIn)) {
    command = "zoom_in";
  } else if (shortcutEquals(shortcut, shortcuts.zoomOut)) {
    command = "zoom_out";
  } else if (shortcutEquals(shortcut, shortcuts.zoomReset)) {
    command = "zoom_reset";
  }

  if (!command) return;

  event.preventDefault();
  event.stopPropagation();
  chrome.runtime.sendMessage({
    type: "shortcutCommand",
    command
  });
}

document.addEventListener("wheel", handleWheel, { passive: false });
document.addEventListener("keydown", handleKeydown, true);

{
  "manifest_version": 3,
  "name": "Fine Zoom Step",
  "version": "0.1.0",
  "description": "Fine-grained tab zoom with keyboard shortcuts and optional Ctrl+Wheel control.",
  "permissions": ["storage", "tabs"],
  "background": { "service_worker": "sw.js" },
  "content_scripts": [
    {
      "matches": ["<all_urls>"],
      "js": ["content.js"],
      "run_at": "document_start",
      "all_frames": true
    }
  ],
  "icons": {
    "16": "icons/icon16.png",
    "32": "icons/icon32.png",
    "48": "icons/icon48.png",
    "128": "icons/icon128.png"
  },
  "action": {
    "default_title": "Fine Zoom",
    "default_popup": "popup.html",
    "default_icon": {
      "16": "icons/icon16.png",
      "32": "icons/icon32.png",
      "48": "icons/icon48.png",
      "128": "icons/icon128.png"
    }
  }
}

:root {
  --ink: #1f1a17;
  --muted: #5c5652;
  --accent: #d66a4a;
  --panel: #fffdf9;
  --line: #e7ddd3;
  --shadow: 0 10px 30px rgba(48, 32, 22, 0.18);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  min-width: 320px;
  color: var(--ink);
  font-family: "Trebuchet MS", "Gill Sans", "Verdana", sans-serif;
  background:
    radial-gradient(circle at 15% 15%, rgba(255, 233, 212, 0.8), transparent 45%),
    radial-gradient(circle at 85% 5%, rgba(255, 214, 186, 0.7), transparent 40%),
    linear-gradient(150deg, #f8efe7 0%, #f6e6d9 100%);
}

.card {
  max-width: 420px;
  margin: 12px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 16px;
  box-shadow: var(--shadow);
  overflow: hidden;
}

.header {
  padding: 24px 28px 20px;
  background: linear-gradient(120deg, #fff2e7, #fde7d2);
  border-bottom: 1px solid var(--line);
}

.header h1 {
  margin: 0 0 6px;
  font-size: 26px;
  letter-spacing: 0.3px;
}

.header p {
  margin: 0;
  color: var(--muted);
}

.section {
  padding: 20px 28px;
  border-bottom: 1px solid var(--line);
}

.section h2 {
  margin: 0 0 12px;
  font-size: 18px;
}

.field {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 0;
  color: var(--ink);
}

.field span {
  flex: 1;
}

.field input[type="number"],
.field input[type="text"],
.field textarea,
.field select {
  width: 220px;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--ink);
  font-size: 14px;
}

.field textarea {
  resize: vertical;
  min-height: 88px;
  font-family: "Consolas", "Courier New", monospace;
}

.field input[type="text"] {
  cursor: pointer;
  font-family: "Consolas", "Courier New", monospace;
}

.field input[type="text"]:focus {
  outline: 2px solid rgba(214, 106, 74, 0.45);
  outline-offset: 1px;
}

.help {
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 12px;
}

.field-stack {
  flex-direction: column;
  align-items: flex-start;
}

.field-stack span {
  flex: 0 0 auto;
}

.field-stack textarea {
  width: 100%;
}

.actions {
  display: flex;
  gap: 10px;
  margin-top: 8px;
}

.btn-ghost {
  background: transparent;
  color: var(--accent);
}

.field.checkbox {
  justify-content: flex-start;
}

.field.checkbox input {
  margin-right: 10px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 0 20px;
}

.footer {
  padding: 16px 28px 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

button {
  padding: 9px 16px;
  border-radius: 999px;
  border: 1px solid var(--accent);
  background: var(--accent);
  color: #fff;
  font-size: 14px;
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}

button:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 14px rgba(214, 106, 74, 0.28);
}

#status {
  color: var(--muted);
  font-size: 13px;
}

#status[data-tone="ok"] {
  color: #2f6f3f;
}

#status[data-tone="error"] {
  color: #b23b28;
}

@media (max-width: 480px) {
  .card {
    margin: 10px;
  }

  .field {
    flex-direction: column;
    align-items: flex-start;
  }

  .field input[type="number"],
  .field input[type="text"],
  .field textarea,
  .field select {
    width: 100%;
  }

  .footer {
    flex-direction: column;
    align-items: flex-start;
  }

  .actions {
    width: 100%;
    flex-direction: column;
  }
}

const DEFAULTS = {
  stepPercent: 1,
  shiftWheelStepPercent: 5,
  shiftWheelMode: "zoom",
  minZoom: 0.25,
  maxZoom: 5,
  ctrlWheelMode: "zoom",
  scrollThreshold: 40,
  minDelayMs: 80,
  directionReversed: false,
  smoothScroll: true,
  shortcuts: {
    zoomIn: "Ctrl+Shift+ArrowUp",
    zoomOut: "Ctrl+Shift+ArrowDown",
    zoomReset: "Ctrl+Shift+0"
  },
  shortcutDisabledHosts: []
};

const fields = {
  stepPercent: document.getElementById("stepPercent"),
  shiftWheelStepPercent: document.getElementById("shiftWheelStepPercent"),
  shiftWheelMode: document.getElementById("shiftWheelMode"),
  ctrlWheelMode: document.getElementById("ctrlWheelMode"),
  scrollThreshold: document.getElementById("scrollThreshold"),
  minDelayMs: document.getElementById("minDelayMs"),
  directionReversed: document.getElementById("directionReversed"),
  smoothScroll: document.getElementById("smoothScroll"),
  shortcutDisabledHosts: document.getElementById("shortcutDisabledHosts")
};

const shortcutFields = {
  zoomIn: document.getElementById("shortcutZoomIn"),
  zoomOut: document.getElementById("shortcutZoomOut"),
  zoomReset: document.getElementById("shortcutZoomReset")
};

const statusEl = document.getElementById("status");
const resetBtn = document.getElementById("reset");
const disableCurrentHostBtn = document.getElementById("disableCurrentHost");
const enableCurrentHostBtn = document.getElementById("enableCurrentHost");

let saveTimer = null;
let statusTimer = null;

function clampNumber(value, min, max, fallback) {
  if (!Number.isFinite(value)) return fallback;
  return Math.min(max, Math.max(min, value));
}

function showStatus(text, tone = "ok") {
  statusEl.textContent = text;
  statusEl.dataset.tone = tone;
  clearTimeout(statusTimer);
  statusTimer = setTimeout(() => {
    statusEl.textContent = "";
    statusEl.dataset.tone = "";
  }, 1200);
}

function readForm() {
  return {
    stepPercent: clampNumber(parseFloat(fields.stepPercent.value), 0.1, 10, DEFAULTS.stepPercent),
    shiftWheelStepPercent: clampNumber(parseFloat(fields.shiftWheelStepPercent.value), 0.1, 20, DEFAULTS.shiftWheelStepPercent),
    shiftWheelMode: fields.shiftWheelMode.value,
    ctrlWheelMode: fields.ctrlWheelMode.value,
    scrollThreshold: clampNumber(parseInt(fields.scrollThreshold.value, 10), 1, 200, DEFAULTS.scrollThreshold),
    minDelayMs: clampNumber(parseInt(fields.minDelayMs.value, 10), 0, 1000, DEFAULTS.minDelayMs),
    directionReversed: fields.directionReversed.checked,
    smoothScroll: fields.smoothScroll.checked,
    shortcutDisabledHosts: parseHostList(fields.shortcutDisabledHosts.value),
    shortcuts: {
      zoomIn: shortcutFields.zoomIn.value.trim(),
      zoomOut: shortcutFields.zoomOut.value.trim(),
      zoomReset: shortcutFields.zoomReset.value.trim()
    }
  };
}

function writeForm(values) {
  const merged = {
    ...DEFAULTS,
    ...values,
    shortcuts: {
      ...DEFAULTS.shortcuts,
      ...(values.shortcuts || {})
    }
  };

  fields.stepPercent.value = merged.stepPercent;
  fields.shiftWheelStepPercent.value = merged.shiftWheelStepPercent;
  fields.shiftWheelMode.value = merged.shiftWheelMode;
  fields.ctrlWheelMode.value = merged.ctrlWheelMode;
  fields.scrollThreshold.value = merged.scrollThreshold;
  fields.minDelayMs.value = merged.minDelayMs;
  fields.directionReversed.checked = merged.directionReversed;
  fields.smoothScroll.checked = merged.smoothScroll;
  fields.shortcutDisabledHosts.value = (merged.shortcutDisabledHosts || []).join("\n");

  shortcutFields.zoomIn.value = merged.shortcuts.zoomIn;
  shortcutFields.zoomOut.value = merged.shortcuts.zoomOut;
  shortcutFields.zoomReset.value = merged.shortcuts.zoomReset;
}

function keyFromCode(code) {
  if (!code) return "";
  if (/^Key[A-Z]$/.test(code)) return code.slice(3);
  if (/^Digit[0-9]$/.test(code)) return code.slice(5);
  if (/^Numpad[0-9]$/.test(code)) return code;

  const direct = new Set([
    "ArrowUp",
    "ArrowDown",
    "ArrowLeft",
    "ArrowRight",
    "Escape",
    "Tab",
    "Enter",
    "Backspace",
    "Delete",
    "Home",
    "End",
    "PageUp",
    "PageDown",
    "Insert",
    "Space",
    "NumpadAdd",
    "NumpadSubtract",
    "NumpadMultiply",
    "NumpadDivide",
    "NumpadDecimal"
  ]);
  if (direct.has(code)) return code;

  return "";
}

function normalizeShortcutKey(event) {
  const codeKey = keyFromCode(event.code);
  if (codeKey) return codeKey;

  const key = event.key;
  if (!key) return "";
  if (key === " ") return "Space";
  if (key === "Esc") return "Escape";
  if (key === "Spacebar") return "Space";

  const modifiers = new Set(["Shift", "Control", "Alt", "Meta"]);
  if (modifiers.has(key)) return "";

  return key.length === 1 ? key.toUpperCase() : key;
}

function buildShortcutFromEvent(event) {
  const key = normalizeShortcutKey(event);
  if (!key) return "";

  const parts = [];
  if (event.ctrlKey) parts.push("Ctrl");
  if (event.altKey) parts.push("Alt");
  if (event.shiftKey) parts.push("Shift");
  if (event.metaKey) parts.push("Meta");
  parts.push(key);
  return parts.join("+");
}

function bindShortcutCapture(field) {
  field.addEventListener("keydown", (event) => {
    event.preventDefault();
    event.stopPropagation();

    if (event.key === "Escape") {
      field.blur();
      return;
    }

    if (event.key === "Backspace" || event.key === "Delete") {
      field.value = "";
      scheduleSave();
      showStatus("Shortcut cleared");
      return;
    }

    const shortcut = buildShortcutFromEvent(event);
    if (!shortcut) return;

    field.value = shortcut;
    scheduleSave();
    showStatus("Shortcut saved");
  });
}

function saveSettings() {
  const values = readForm();
  const validationError = validateShortcuts(values.shortcuts);
  if (validationError) {
    showStatus(validationError, "error");
    return;
  }
  chrome.storage.sync.set(values, () => showStatus("Saved"));
}

function scheduleSave() {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(saveSettings, 150);
}

function validateShortcuts(shortcuts) {
  const normalized = Object.values(shortcuts || {})
    .map((value) => String(value || "").trim())
    .filter(Boolean)
    .map((value) => value.toLowerCase());

  if (normalized.length === 0) {
    return "Keep at least one shortcut";
  }

  const seen = new Set();
  for (const value of normalized) {
    if (seen.has(value)) {
      return "Shortcuts must be unique";
    }
    seen.add(value);
  }

  return "";
}

function normalizeHostToken(rawValue) {
  const trimmed = String(rawValue || "").trim().toLowerCase();
  if (!trimmed) return "";

  let value = trimmed.replace(/^[a-z]+:\/\//i, "");
  value = value.split(/[/?#]/)[0] || "";
  value = value.split(":")[0] || "";
  value = value.replace(/^\./, "").trim();

  if (!value || /\s/.test(value)) return "";
  return value;
}

function parseHostList(textValue) {
  const parts = String(textValue || "")
    .split(/[\n,]/)
    .map((part) => normalizeHostToken(part))
    .filter(Boolean);
  return Array.from(new Set(parts));
}

async function getActiveTabHostname() {
  const tabs = await chrome.tabs.query({ active: true, lastFocusedWindow: true });
  const tab = tabs[0];
  if (!tab?.url) return "";
  try {
    const url = new URL(tab.url);
    return normalizeHostToken(url.hostname);
  } catch {
    return "";
  }
}

function updateDisabledHostsField(hostname, shouldDisable) {
  if (!hostname) {
    showStatus("Host not available on this page", "error");
    return;
  }

  const current = parseHostList(fields.shortcutDisabledHosts.value);
  const next = shouldDisable
    ? Array.from(new Set([...current, hostname]))
    : current.filter((item) => item !== hostname);

  fields.shortcutDisabledHosts.value = next.join("\n");
  scheduleSave();
  showStatus(shouldDisable ? `Disabled on ${hostname}` : `Enabled on ${hostname}`);
}

function loadSettings() {
  chrome.storage.sync.get(DEFAULTS, (items) => {
    writeForm(items);
  });
}

const normalFields = Object.values(fields);
normalFields.forEach((field) => {
  field.addEventListener("input", scheduleSave);
  field.addEventListener("change", scheduleSave);
});

Object.values(shortcutFields).forEach((field) => {
  bindShortcutCapture(field);
});

resetBtn.addEventListener("click", () => {
  chrome.storage.sync.set(DEFAULTS, () => {
    loadSettings();
    showStatus("Defaults restored");
  });
});

disableCurrentHostBtn.addEventListener("click", () => {
  getActiveTabHostname()
    .then((hostname) => updateDisabledHostsField(hostname, true))
    .catch(() => showStatus("Unable to read current host", "error"));
});

enableCurrentHostBtn.addEventListener("click", () => {
  getActiveTabHostname()
    .then((hostname) => updateDisabledHostsField(hostname, false))
    .catch(() => showStatus("Unable to read current host", "error"));
});

loadSettings();

const DEFAULTS = {
  stepPercent: 1,
  shiftWheelStepPercent: 5,
  shiftWheelMode: "zoom", // off | zoom
  minZoom: 0.25,
  maxZoom: 5,
  ctrlWheelMode: "zoom", // off | zoom | block
  scrollThreshold: 40,
  minDelayMs: 80,
  directionReversed: false,
  smoothScroll: true,
  shortcuts: {
    zoomIn: "Ctrl+Shift+ArrowUp",
    zoomOut: "Ctrl+Shift+ArrowDown",
    zoomReset: "Ctrl+Shift+0"
  },
  shortcutDisabledHosts: []
};

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function roundZoom(value) {
  return Number(value.toFixed(3));
}

function logError(context, error) {
  const message = error && error.message ? error.message : String(error || "Unknown error");
  console.warn(`[Fine Zoom Step] ${context}: ${message}`);
}

async function getSettings() {
  const items = await chrome.storage.sync.get(DEFAULTS);
  return {
    ...DEFAULTS,
    ...items,
    shortcuts: {
      ...DEFAULTS.shortcuts,
      ...(items.shortcuts || {})
    }
  };
}

async function applyZoomDelta(tabId, deltaPercent, settingsOverride) {
  const settings = settingsOverride || (await getSettings());
  const current = await chrome.tabs.getZoom(tabId);
  const next = clamp(
    roundZoom(current + deltaPercent / 100),
    settings.minZoom,
    settings.maxZoom
  );
  await chrome.tabs.setZoom(tabId, next);
}

async function applyCommand(tabId, command) {
  if (command === "zoom_reset") {
    await chrome.tabs.setZoom(tabId, 0);
    return;
  }

  const settings = await getSettings();
  if (command === "zoom_in") {
    await applyZoomDelta(tabId, settings.stepPercent, settings);
  } else if (command === "zoom_out") {
    await applyZoomDelta(tabId, -settings.stepPercent, settings);
  }
}

chrome.runtime.onMessage.addListener((message, sender) => {
  if (!message) return;
  const tabId = sender?.tab?.id;
  if (!tabId) return;

  if (message.type === "shortcutCommand") {
    applyCommand(tabId, message.command).catch((error) => {
      logError("shortcutCommand", error);
    });
    return;
  }

  if (message.type === "wheelZoom") {
    const direction = message.direction === 1 ? 1 : -1;
    getSettings()
      .then((settings) => {
        const requestedStep = Number(message.stepPercent);
        const stepPercent =
          Number.isFinite(requestedStep) && requestedStep > 0
            ? requestedStep
            : settings.stepPercent;
        return applyZoomDelta(tabId, direction * stepPercent, settings);
      })
      .catch((error) => {
        logError("wheelZoom", error);
      });
  }
});

chrome.runtime.onInstalled.addListener(() => {
  chrome.storage.sync.get(null, (items) => {
    chrome.storage.sync.set({
      ...DEFAULTS,
      ...items,
      shortcuts: {
        ...DEFAULTS.shortcuts,
        ...(items.shortcuts || {})
      }
    });
  });
});
